const CP = (c: Checkpoint): Checkpoint => c;

export const JSM_PRACTICALS: Record<string, Practical> = {
  "l4-jsm-types": { task: "A form delivers the port as the string \"443\". Which expression correctly tests 'is HTTPS'?", options: ["port == 443", "Number(port) === 443 — convert explicitly at the boundary, then compare strictly", "port + 0 === \"443\"", "typeof port === 443"], answer: 1, explain: "== would also pass (coercion), which is exactly the habit this lesson removes: convert once, compare with === forever after.", hint: "Boundary conversion first, strict comparison second." },
  "l4-jsm-control": { task: "classify(500) with arms for 200, 404, a 500–599 range check, and a default returns:", options: ["'Not found'", "'Server error' — the range check catches 500 before the default", "An exception", "'OK'"], answer: 1, explain: "Arm order is logic: literals first, the range next, the default last — 500 walks past 200 and 404 into the range arm.", hint: "Walk the value through the arms top to bottom." },
  "l4-jsm-functions": { task: "A counter factory is called twice: const a = makeCounter(); const b = makeCounter(); a(); a(); b(); — the three printed values are:", options: ["1, 2, 3", "1, 2, 1 — each call to the factory creates an INDEPENDENT closure variable", "1, 1, 1", "2, 2, 2"], answer: 1, explain: "Closures capture per-call state: a's count and b's count are separate variables living in separate closure scopes.", hint: "Ask: how many 'count' variables exist after two factory calls?" },
  "l4-jsm-arrays": { task: "ports = [3389, 22, 443, 23]; ports.filter(p => p > 1000) and the ORIGINAL array afterwards:", options: ["[3389] and ports is unchanged — filter returns a NEW array", "[3389, 443] and ports changed", "[3389] and ports becomes [3389]", "An error"], answer: 0, explain: "filter/map return new arrays; only mutators (push, splice, sort in place) change the original. 443 is not > 1000.", hint: "Two questions: what passes the predicate, and does filter mutate?" },
  "l4-jsm-objects": { task: "JSON.parse('{\"port\":\"443\"}') gives an object whose port, tested with === 443, is:", options: ["true", "false — JSON preserved the STRING type from the text; convert with Number() before strict comparison", "An error", "undefined"], answer: 1, explain: "JSON round-trips types as written: quotes in the text mean a string in the object. The types lesson applies at the JSON border too.", hint: "What do the quotes around 443 in the JSON text mean?" },
  "l4-jsm-dom": { task: "A page must show a username that came from a URL parameter. The safe rendering choice is:", options: ["el.innerHTML = name", "el.textContent = name — text assignment can never create elements, so markup in the value stays inert text", "document.write(name)", "el.innerHTML = escape(name) with a hand-rolled escaper"], answer: 1, explain: "textContent is the structural fix: the browser never parses it as HTML. Hand-rolled escaping is the fragile second choice.", hint: "Which API never invokes the HTML parser?" },
  "l4-jsm-events": { task: "A click handler reads a port from an input and must reject 'abc'. The correct guard is:", options: ["if (value) — truthiness", "const n = Number(value); if (Number.isInteger(n) && n >= 1 && n <= 65535) — convert, then test shape and range in layers", "if (value !== '')", "try { value.toNumber() } catch"], answer: 1, explain: "'abc' is truthy, so truthiness accepts it. Layered validation — convert, integer test, range test — is the input lesson's discipline in JS spelling.", hint: "Truthiness is about emptiness, not validity." },
  "l4-jsm-async": { task: "Two checks run with Promise.all([check('a', 20), check('b', 5)]). b finishes first. The results array order is:", options: ["b, a — completion order", "a, b — Promise.all preserves INPUT order regardless of completion order", "Whichever — it varies run to run", "An error"], answer: 1, explain: "Promise.all's contract: results align with the input array positions. Timing decides when, never where.", hint: "The async lesson's lines state the contract explicitly." },
  "l4-jsm-es6": { task: "const { port = 443, ...rest } = { host: 'lab-web', port: 23, user: 'rahim' }; — port and rest are:", options: ["443 and {host, user}", "23 and { host: 'lab-web', user: 'rahim' } — the default applies only when the key is ABSENT; rest collects the remaining keys", "23 and { port: 23 }", "undefined and the whole object"], answer: 1, explain: "Defaults fire on absence (or undefined), not on presence; rest gathers what destructuring did not name.", hint: "Is the port key present in the object?" },
  "l4-jsm-security": { task: "Building a query URL from user input name = 'a&admin=true'. The safe construction is:", options: ["`?name=${name}`", "`?name=${encodeURIComponent(name)}` — encoding makes the & and = DATA inside the value, not new parameters", "name.replace('&', '')", "It is safe as-is"], answer: 1, explain: "Unencoded input lets the value break out of its parameter — parameter injection. encodeURIComponent is the boundary control.", hint: "What does the & mean to the URL parser if it arrives raw?" },
};

